package net.officefloor.hq.app.holiday;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** A date already on the sheet's list of holidays is refused. */
public class SaveHoliday {
    public void save(@Val HolidayInput input, @Val Sheet sheet, HolidayRepository repository,
            Out<Holiday> holidayOut) throws InvalidHolidayException {
        if (repository.exists(sheet.id(), input.date())) {
            throw new InvalidHolidayException(input.date() + " is already a holiday");
        }
        Holiday holiday = new Holiday(sheet.id(), input.date());
        repository.save(holiday);
        holidayOut.set(holiday);
    }
}
=== java/net/officefloor/hq/app/holiday/ValidateHoliday.java
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateHoliday {
    public void validate(@RequestBody HolidayRequest request, Out<HolidayInput> body) throws InvalidHolidayException {
        String date = request == null || request.date() == null ? "" : request.date().trim();
        if (date.isEmpty()) throw new InvalidHolidayException("A holiday's date is required");
        try {
            body.set(new HolidayInput(LocalDate.parse(date)));
        } catch (DateTimeParseException e) {
            throw new InvalidHolidayException("A date is yyyy-MM-dd");
        }
    }
}
