import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** A grade in force from a date (yyyy-MM-dd; '' from the beginning of time) until the next one. */
export type GradeFrom = { from: string; grade: Grade };

/** The grade in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it. */
export function gradeOn(grades: GradeFrom[], date: string): Grade {
  let best = grades[0];
  for (const g of grades) if (g.from <= date && g.from >= best.from) best = g;
  return best.grade;
}

// `version` is raised by each save; an edit sends the version it was made from. `statementCount`
// is how many statements have been taken for them; `statedTotal` and `statementDate` are the last
// one's due-total and date ('' before the first). `retired` is set once they have a retirement
// date, `retiredFrom` ('' when not retired), whatever that date is. `held` is whether they have any hold; `holds` their holds in the order added (see `Hold`).
// `patronIds` are the ids of the people they name as their patrons. `grade` is the grade in force on
// the sheet's today; `grades` every grade they have been given, by from-date, the first from ''.
// `terms` are their own terms in days, ahead of their grade's and the sheet's ('' for none).
// `contact` is their contact, trimmed and lower-cased ('' for none); no two people on a sheet share one.
// `aliases` are their aliases, trimmed, in the order given; like names (ignoring case), none equals
// any name or alias on the sheet.
export type Person = {
  id: string;
  name: string;
  grade: Grade;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  holds: Hold[];
  patronIds: string[];
  grades: GradeFrom[];
  terms: string;
  contact: string;
  aliases: string[];
};

/**
 * A hold on a person: from a date to a date (yyyy-MM-dd; `to` '' when open-ended), both inclusive.
 * An OPEN or PENDING claim of theirs dated within one, unless a statement binds it, counts in no total.
 */
export type Hold = { from: string; to: string };

/** Whether the date (yyyy-MM-dd) is within one of the holds. */
export const heldOn = (holds: Hold[], date: string) =>
  holds.some((h) => h.from <= date && (h.to === '' || date <= h.to));

/**
 * The holds a person's claims count against on the sheet's `today`: their own, and from the day
 * their retirement date is reached (`today` on or after it) one covering every date — their OPEN
 * and PENDING claims, unless a statement binds them, then count in no total.
 */
export const liveHolds = (p: Pick<Person, 'holds' | 'retiredFrom'>, today: string): Hold[] =>
  p.retiredFrom !== '' && today !== '' && p.retiredFrom <= today ? [...p.holds, { from: '', to: '' }] : p.holds;

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: async () =>
    (await getJson<{ people: Person[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/people`)).people,
});

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery(peopleQuery(sheetId));
}

/** Whether retired people are listed. Off when the screen is first opened; loading a sheet keeps it. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx response, carrying its status so a caller can tell one refusal from another.
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

// The as-of date the screen reads the sheet at ('' for now): the `asof` search param. While it is set
// every read names it, so the server answers with the sheet as it stood then, and every change is
// refused here, never sent — the form that made it shows its usual error. Loading a sheet is no
// change: it only re-reads one.
export const ASOF_PARAM = 'asof';

function asOf(): string {
  return new URLSearchParams(window.location.search).get(ASOF_PARAM) ?? '';
}

function refuseWhileAsOf(method: string, path: string): void {
  if (asOf() !== '' && !path.endsWith('/load')) {
    throw new HttpError(`${method} ${path} -> refused while viewing as of ${asOf()}`, 409);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

// A read that depends on who is signed in names them too.
export function getJson<T>(path: string, user?: string): Promise<T> {
  const headers: Record<string, string> = {};
  if (user !== undefined) headers['X-User'] = encodeURIComponent(user);
  const date = asOf();
  if (date !== '') headers['X-As-Of'] = date;
  return send<T>(path, { headers });
}

// A change is made by the signed-in user: name them, and the server records who made it.
function jsonHeaders(user?: string): HeadersInit {
  return user === undefined
    ? { 'Content-Type': 'application/json' }
    : { 'Content-Type': 'application/json', 'X-User': encodeURIComponent(user) };
}

export async function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  refuseWhileAsOf('POST', path);
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export async function putJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  refuseWhileAsOf('PUT', path);
import { useRef } from 'react';

// A form submitted twice before its first submit has answered (a double click) must store one
// record, not two. A mutation's isPending reaches the button only after a re-render, too late for
// the second click, so a submit is guarded by a ref that is set at once: `once(done => ...)` runs
// the start only when nothing is in flight, and the start calls `done` when its request settles.
export function useOnce() {
  const busy = useRef(false);
  return (start: (done: () => void) => void) => {
    if (busy.current) return;
    busy.current = true;
    start(() => {
      busy.current = false;
    });
  };
}
